const $=(s,root=document)=>root.querySelector(s);const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const menu=$('.menu-toggle');const navigation=$('.nav-links');menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));navigation.classList.toggle('open',open);menu.textContent=open?'Close':'Menu'});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&navigation?.classList.contains('open')){navigation.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='Menu';menu.focus()}});
const sizes=['Small: compact cars and hatchbacks.','Medium: sedans and crossovers.','Large: SUVs and utes.'];$$('[data-size]').forEach(button=>button.addEventListener('click',()=>{const n=Number(button.dataset.size);$$('[data-size]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));$$('[data-price]').forEach(el=>el.textContent='$'+el.dataset.price.split(',')[n]);$$('[data-service-link]').forEach(el=>el.href=`/book/?service=${el.dataset.serviceLink}&size=${n}`);$('#size-description').textContent=sizes[n]}));
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const hero=$('#hero-video');const pause=$('.video-toggle');if(hero){if(reduced){hero.pause();pause.textContent='Play film';pause.setAttribute('aria-label','Play background video')}pause.addEventListener('click',async()=>{if(hero.paused){try{await hero.play()}catch{}}else hero.pause();pause.textContent=hero.paused?'Play film':'Pause film';pause.setAttribute('aria-label',hero.paused?'Play background video':'Pause background video')});hero.addEventListener('error',()=>{pause.hidden=true})}
document.addEventListener('play',event=>{if(event.target.matches?.('.work-video'))$$('.work-video').forEach(video=>{if(video!==event.target)video.pause()})},true);
const form=$('#booking-form');if(form){const prices={complete:[90,105,125],outside:[50,60,70],inside:[50,60,70]};const names={complete:'Detailed Clean (inside & out)',outside:'Detailed Outside',inside:'Detailed Inside'};const query=new URLSearchParams(location.search);if(query.has('service')&&Object.hasOwn(prices,query.get('service')))$('#service').value=query.get('service');if(['0','1','2'].includes(query.get('size')))$('#size').value=query.get('size');const date=new Date();const localToday=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;$('#date').min=localToday;const update=()=>{$('#booking-price').textContent='$'+prices[$('#service').value][Number($('#size').value)];$('#form-status').hidden=true};$('#service').addEventListener('change',update);$('#size').addEventListener('change',update);update();
 const send=method=>{if(!form.reportValidity())return;const d=Object.fromEntries(new FormData(form));const number=d.phone.replace(/[^\d+]/g,'');if(number.replace(/\D/g,'').length<8){$('#phone').setCustomValidity('Please enter a valid contact number.');$('#phone').reportValidity();return}const chosen=new Date(d.date+'T12:00:00').toLocaleDateString('en-AU',{weekday:'short',day:'numeric',month:'short',year:'numeric'});const text=`Hi Refined Detailing, I’d like to book a detail.\n\nName: ${d.name.trim()}\nPhone: ${d.phone.trim()}\nService: ${names[d.service]}\nVehicle size: ${['Small','Medium','Large'][Number(d.size)]}\nVehicle: ${d.vehicle.trim()}\nPreferred date: ${chosen}\nPreferred time: ${d.time||'Flexible'}\nSuburb: ${d.suburb.trim()}\nNotes: ${d.notes.trim()||'None'}\nGuide price: $${prices[d.service][Number(d.size)]}\n\nPlease confirm availability and the final price. Thanks!`;const status=$('#form-status');status.replaceChildren();const message=document.createElement('p');message.textContent=`Your ${method==='sms'?'text message':'email'} is ready. Send it from your app to request the booking. If the app didn’t open, copy the details below.`;const pre=document.createElement('pre');pre.textContent=text;const copy=document.createElement('button');copy.type='button';copy.className='btn outline';copy.textContent='Copy booking details';copy.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(text);copy.textContent='Copied'}catch{copy.textContent='Select the details above to copy'}});status.append(message,pre,copy);status.hidden=false;const apple=/iPhone|iPad|iPod/.test(navigator.userAgent);location.href=method==='sms'?`sms:+61431484541${apple?'&':'?'}body=${encodeURIComponent(text)}`:`mailto:refined.detailing.newcastle@gmail.com?subject=${encodeURIComponent('Detail booking — '+d.vehicle.trim())}&body=${encodeURIComponent(text)}`};form.addEventListener('submit',e=>{e.preventDefault();send('sms')});$('#email-booking').addEventListener('click',()=>send('email'));$('#phone').addEventListener('input',()=>$('#phone').setCustomValidity(''));form.addEventListener('input',()=>$('#form-status').hidden=true)}
if('IntersectionObserver'in window&&!reduced){const observer=new IntersectionObserver(items=>{items.forEach(item=>{if(item.isIntersecting){item.target.classList.add('visible');observer.unobserve(item.target)}})},{threshold:.08});$$('.section-head,.intro-copy,.process-item,.about-values>div').forEach(el=>{el.classList.add('reveal','js-reveal');observer.observe(el)})}
